cd <scratch>/s1/R1 && mkdir -p work && cat > work/q.tuft <<'E'
@h := find text "claim_matches_spec(" in "crates/" at "c568505742d00859cad758924c98d8d0a6e98648" limit 100;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)];
emit @v budget_tokens 4000;
E
cd work && <writfold> tuft run q.tuft --repo ../repo --state ../state --out out.txt; cat out.txt
